// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    // fuzzed parameters: from address and a single recipient address and a uint value
    // we use arrays in the call; the fuzzer will vary addresses and v
    function testFuzz_property(address from, address recipient, uint256 v) public {
        // keep recipients non-zero and distinct-ish: require non-zero recipient to be admissible
        vm.assume(recipient != address(0));
        vm.assume(from != address(0));

        // Deploy a helper that will revert when called. This models an external counterparty that fails.
        Reverter reverter = new Reverter();

        // Prepare _tos array with exactly one entry to make observations simple
        address[] memory tos = new address[](1);
        tos[0] = address(reverter);

        // CALL c.transfer and observe whether it reverts.
        // For the correct implementation P, the external call to reverter will revert, so c.transfer should revert.
        // For the mutant M (which removed the external call), c.transfer will not revert.
        bool ok;
        try c.transfer(from, address(reverter), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule (single assert): for any admissible inputs (non-empty tos), when the callee reverts,
        // the reference implementation propagates the revert, so ok must be false. The mutant that removed
        // the call will yield ok == true for some inputs; the fuzzer will find them.
        assertTrue(ok == false);
    }
}

contract Reverter {
    // this contract reverts on any call that matches transferFrom selector or fallback
    fallback() external payable {
        revert("revert from callee");
    }
    receive() external payable {
        revert("revert from callee");
    }
    // also provide the exact signature optionally targeted by C so that ABI decoding happens
    function transferFrom(address, address, uint256) external {
        revert("revert from transferFrom");
    }
}
